UPDATE digital_team_coordinator_dispatch SET status = #{status}, last_error = #{error},
lease_owner = NULL, lease_expires_at = NULL, updated_at = CURRENT_TIMESTAMP
WHERE business_id = #{dispatchId}

UPDATE digital_team_coordinator_dispatch SET status = 'PENDING',
available_at = CURRENT_TIMESTAMP, lease_owner = NULL,
lease_expires_at = NULL WHERE business_id = #{dispatchId}
AND tenant_id = #{tenantId}
